import java.io.*;
import java.util.*;
import java.util.stream.*;

public final class Solution extends Helper {
    public void __main(int _TCID) {
        String dummy = readWordString();
        char[] s = readWordString().toCharArray();
        int n = s.length;
        int upb = n - 1;

        ValueRefPointer<Long> res = new ValueRefPointer<>();
        res.ValueNullable = (long) n;

        seq(1, upb).stream()
            .takeWhile(i -> countLength(0, i - 1) <= countLength(i, upb))
            .forEach(i -> {
                long leftCount = countLength(0, i - 1);
                long rightCount = countLength(i, upb);
                if (leftCount <= 0) return;
                int leftLen = (int) leftCount;
                int rightStart = i;
                int rightEnd = (int) getRight(i, leftCount);
                if (rightEnd >= n) return;
                boolean equal = true;
                for (int a = 0; a < leftLen; a++) {
                    if (s[a] != s[rightStart + a]) {
                        equal = false;
                        break;
                    }
                }
                if (equal) {
                    long val = 1L + i + (n - i - leftCount);
                    res.UpdateCompute(val, Math::min);
                }
            });

        writeNumber(res.ValueNullable != null ? res.ValueNullable : 1L);
        writeLine();
    }

    public static void main(String[] args) {
        __stdioMain();
    }
}

